window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6e695b3447703dcb"]={"versions": [{"id": "FIG-6e695b3447703dcb", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Speicherschutzdiagramm (AUTOSAR Classic Platform, Schichtenarchitektur im Kontext des Safety Concept Status Reports). Das Diagramm visualisiert das Konzept der Speicherpartitionierung (Memory Partitioning) und CPU-Betriebsmodi (CPU User Mode vs. CPU Supervisor Mode) zur Trennung von vertrauenswürdigen (trusted) und nicht-vertrauenswürdigen (non-trusted) OS-Applications, inklusive der Zuordnung von Software-Komponenten (SW-Cs) und Basissoftware-Modulen (BSWMs) sowie der Speicheraufteilung in private und geteilte Bereiche.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich vertikal in ECU-Hardware, Basic Software (BSW), AUTOSAR Runtime Environment (RTE) und die AUTOSAR-Software-Anwendungsschicht.</p>\n<ul class=\"fig-list\">\n<li>Entitäten und Partitionen:</li>\n<li>Nicht-vertrauenswürdige Partitionen (grün umrandet, CPU User Mode): „Non-trusted OS-Applications, with protection enabled“. SW-Cs sind einer oder mehreren OS-Applications zugeordnet (z. B. linke Application Software Component in einer eigenen Partition; Actuator Software Component und Sensor Software Component gemeinsam in einer weiteren Partition).</li>\n<li>Vertrauenswürdige Partition (rot hinterlegt/umrandet, CPU Supervisor Mode): Bildet „OS-Application 1, trusted, with protection disabled“. Diese umfasst sämtliche Basissoftware-Module, die RTE sowie ausgewählte vertrauenswürdige Anwendungs-SW-Cs (vierte Application Software Component).</li>\n<li>BSW-Module: Operating System (OS), Services, Communication, ECU Abstraction, Microcontroller Abstraction (MCAL) und Complex Device Drivers (CDD).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellen:</li>\n<li>AUTOSAR Interface: Zwischen Anwendungs-SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li>Standardized AUTOSAR Interface: Zwischen RTE und Services.</li>\n<li>Standardized Interface: Zwischen RTE und BSW (Services, Communication, OS-Schnittstellenblock), zwischen BSW-Modulen untereinander (Services, Communication, ECU Abstraction zum OS; ECU Abstraction zu MCAL) sowie an der vertikalen OS-Schnittstelle („Standardized Inteface“).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Speicheraufteilung (Memory-Säule rechts):</li>\n<li>Private Datenbereiche: OS-App 1 private data, OS-App 2 private data, ..., OS-App n private data.</li>\n<li>Private Codebereiche: OS-App 1 private code, OS-App 2 private code, ..., OS-App n private code.</li>\n<li>Geteilter Speicherbereich: „Optional: shared OS-App 1 data (buffer used by RTE for IPC)“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsdiagramm ohne explizite Ablauf- oder Zeitsequenzen. Das dynamische Zusammenspiel basiert auf den Privilegiierungsstufen:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs in nicht-vertrauenswürdigen Partitionen führen Code im CPU User Mode aus; Speicherzugriffe werden hardwaregestützt (MPU) auf die jeweiligen privaten Daten- und Codebereiche begrenzt.</li>\n<li>BSW-Module und vertrauenswürdige SW-Cs führen Code im CPU Supervisor Mode ohne Zugriffsbeschränkungen aus.</li>\n<li>Inter-OS-Application-Kommunikation (IPC) zwischen Partitionen erfolgt vermittelt über die RTE unter Verwendung definierter Puffer im Shared Memory („shared OS-App 1 data“). BSW-Dienste werden über standardisierte Schnittstellen und Systemaufrufe an das Betriebssystem angefordert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sicherheitstechnisches Architekturmuster zur Gewährleistung der Rückwirkungsfreiheit (Freedom from Interference gemäß ISO 26262):</p>\n<ul class=\"fig-list\">\n<li>Basissoftware und ausgewählte funktionale SW-Cs können in einer gemeinsamen vertrauenswürdigen Partition (OS-Application 1, Supervisor Mode) ausgeführt werden, wenn sie demselben Integritätslevel entsprechen oder gemeinsam qualifiziert sind.</li>\n<li>Nicht-vertrauenswürdige Software-Komponenten müssen in getrennte User-Mode-OS-Applications ausgelagert werden, um Schutz vor unberechtigten Speicherüberschreibungen fremder Applikationen oder der Basissoftware sicherzustellen.</li>\n<li>Datenflüsse zwischen unterschiedlichen Sicherheitsdomänen dürfen nicht direkt über ungeschützte globale Variablen abgewickelt werden, sondern erfordern RTE-vermittelte Schnittstellen und kontrollierte Kommunikationspuffer.</li>\n</ul>"}, {"id": "FIG-b7f603315cf2ab59", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Speicherschutzdiagramm (AUTOSAR Classic Platform, Schichtenarchitektur im Kontext des Safety Concept Status Reports). Das Diagramm visualisiert das Konzept der Speicherpartitionierung (Memory Partitioning) und CPU-Betriebsmodi (CPU User Mode vs. CPU Supervisor Mode) zur Trennung von vertrauenswürdigen (trusted) und nicht-vertrauenswürdigen (non-trusted) OS-Applications, inklusive der Zuordnung von Software-Komponenten (SW-Cs) und Basissoftware-Modulen (BSWMs) sowie der Speicheraufteilung in private und geteilte Bereiche.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich vertikal in ECU-Hardware, Basic Software (BSW), AUTOSAR Runtime Environment (RTE) und die AUTOSAR-Software-Anwendungsschicht.</p>\n<ul class=\"fig-list\">\n<li>Entitäten und Partitionen:</li>\n<li>Nicht-vertrauenswürdige Partitionen (grün umrandet, CPU User Mode): „Non-trusted OS-Applications, with protection enabled“. SW-Cs sind einer oder mehreren OS-Applications zugeordnet (z. B. linke Application Software Component in einer eigenen Partition; Actuator Software Component und Sensor Software Component gemeinsam in einer weiteren Partition).</li>\n<li>Vertrauenswürdige Partition (rot hinterlegt/umrandet, CPU Supervisor Mode): Bildet „OS-Application 1, trusted, with protection disabled“. Diese umfasst sämtliche Basissoftware-Module, die RTE sowie ausgewählte vertrauenswürdige Anwendungs-SW-Cs (vierte Application Software Component).</li>\n<li>BSW-Module: Operating System (OS), Services, Communication, ECU Abstraction, Microcontroller Abstraction (MCAL) und Complex Device Drivers (CDD).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellen:</li>\n<li>AUTOSAR Interface: Zwischen Anwendungs-SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li>Standardized AUTOSAR Interface: Zwischen RTE und Services.</li>\n<li>Standardized Interface: Zwischen RTE und BSW (Services, Communication, OS-Schnittstellenblock), zwischen BSW-Modulen untereinander (Services, Communication, ECU Abstraction zum OS; ECU Abstraction zu MCAL) sowie an der vertikalen OS-Schnittstelle („Standardized Inteface“).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Speicheraufteilung (Memory-Säule rechts):</li>\n<li>Private Datenbereiche: OS-App 1 private data, OS-App 2 private data, ..., OS-App n private data.</li>\n<li>Private Codebereiche: OS-App 1 private code, OS-App 2 private code, ..., OS-App n private code.</li>\n<li>Geteilter Speicherbereich: „Optional: shared OS-App 1 data (buffer used by RTE for IPC)“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsdiagramm ohne explizite Ablauf- oder Zeitsequenzen. Das dynamische Zusammenspiel basiert auf den Privilegiierungsstufen:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs in nicht-vertrauenswürdigen Partitionen führen Code im CPU User Mode aus; Speicherzugriffe werden hardwaregestützt (MPU) auf die jeweiligen privaten Daten- und Codebereiche begrenzt.</li>\n<li>BSW-Module und vertrauenswürdige SW-Cs führen Code im CPU Supervisor Mode ohne Zugriffsbeschränkungen aus.</li>\n<li>Inter-OS-Application-Kommunikation (IPC) zwischen Partitionen erfolgt vermittelt über die RTE unter Verwendung definierter Puffer im Shared Memory („shared OS-App 1 data“). BSW-Dienste werden über standardisierte Schnittstellen und Systemaufrufe an das Betriebssystem angefordert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sicherheitstechnisches Architekturmuster zur Gewährleistung der Rückwirkungsfreiheit (Freedom from Interference gemäß ISO 26262):</p>\n<ul class=\"fig-list\">\n<li>Basissoftware und ausgewählte funktionale SW-Cs können in einer gemeinsamen vertrauenswürdigen Partition (OS-Application 1, Supervisor Mode) ausgeführt werden, wenn sie demselben Integritätslevel entsprechen oder gemeinsam qualifiziert sind.</li>\n<li>Nicht-vertrauenswürdige Software-Komponenten müssen in getrennte User-Mode-OS-Applications ausgelagert werden, um Schutz vor unberechtigten Speicherüberschreibungen fremder Applikationen oder der Basissoftware sicherzustellen.</li>\n<li>Datenflüsse zwischen unterschiedlichen Sicherheitsdomänen dürfen nicht direkt über ungeschützte globale Variablen abgewickelt werden, sondern erfordern RTE-vermittelte Schnittstellen und kontrollierte Kommunikationspuffer.</li>\n</ul>"}, {"id": "FIG-4af1386b469f084e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Speicherschutzdiagramm (AUTOSAR Classic Platform, Schichtenarchitektur im Kontext des Safety Concept Status Reports). Das Diagramm visualisiert das Konzept der Speicherpartitionierung (Memory Partitioning) und CPU-Betriebsmodi (CPU User Mode vs. CPU Supervisor Mode) zur Trennung von vertrauenswürdigen (trusted) und nicht-vertrauenswürdigen (non-trusted) OS-Applications, inklusive der Zuordnung von Software-Komponenten (SW-Cs) und Basissoftware-Modulen (BSWMs) sowie der Speicheraufteilung in private und geteilte Bereiche.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich vertikal in ECU-Hardware, Basic Software (BSW), AUTOSAR Runtime Environment (RTE) und die AUTOSAR-Software-Anwendungsschicht.</p>\n<ul class=\"fig-list\">\n<li>Entitäten und Partitionen:</li>\n<li>Nicht-vertrauenswürdige Partitionen (grün umrandet, CPU User Mode): „Non-trusted OS-Applications, with protection enabled“. SW-Cs sind einer oder mehreren OS-Applications zugeordnet (z. B. linke Application Software Component in einer eigenen Partition; Actuator Software Component und Sensor Software Component gemeinsam in einer weiteren Partition).</li>\n<li>Vertrauenswürdige Partition (rot hinterlegt/umrandet, CPU Supervisor Mode): Bildet „OS-Application 1, trusted, with protection disabled“. Diese umfasst sämtliche Basissoftware-Module, die RTE sowie ausgewählte vertrauenswürdige Anwendungs-SW-Cs (vierte Application Software Component).</li>\n<li>BSW-Module: Operating System (OS), Services, Communication, ECU Abstraction, Microcontroller Abstraction (MCAL) und Complex Device Drivers (CDD).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellen:</li>\n<li>AUTOSAR Interface: Zwischen Anwendungs-SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li>Standardized AUTOSAR Interface: Zwischen RTE und Services.</li>\n<li>Standardized Interface: Zwischen RTE und BSW (Services, Communication, OS-Schnittstellenblock), zwischen BSW-Modulen untereinander (Services, Communication, ECU Abstraction zum OS; ECU Abstraction zu MCAL) sowie an der vertikalen OS-Schnittstelle („Standardized Inteface“).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Speicheraufteilung (Memory-Säule rechts):</li>\n<li>Private Datenbereiche: OS-App 1 private data, OS-App 2 private data, ..., OS-App n private data.</li>\n<li>Private Codebereiche: OS-App 1 private code, OS-App 2 private code, ..., OS-App n private code.</li>\n<li>Geteilter Speicherbereich: „Optional: shared OS-App 1 data (buffer used by RTE for IPC)“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsdiagramm ohne explizite Ablauf- oder Zeitsequenzen. Das dynamische Zusammenspiel basiert auf den Privilegiierungsstufen:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs in nicht-vertrauenswürdigen Partitionen führen Code im CPU User Mode aus; Speicherzugriffe werden hardwaregestützt (MPU) auf die jeweiligen privaten Daten- und Codebereiche begrenzt.</li>\n<li>BSW-Module und vertrauenswürdige SW-Cs führen Code im CPU Supervisor Mode ohne Zugriffsbeschränkungen aus.</li>\n<li>Inter-OS-Application-Kommunikation (IPC) zwischen Partitionen erfolgt vermittelt über die RTE unter Verwendung definierter Puffer im Shared Memory („shared OS-App 1 data“). BSW-Dienste werden über standardisierte Schnittstellen und Systemaufrufe an das Betriebssystem angefordert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sicherheitstechnisches Architekturmuster zur Gewährleistung der Rückwirkungsfreiheit (Freedom from Interference gemäß ISO 26262):</p>\n<ul class=\"fig-list\">\n<li>Basissoftware und ausgewählte funktionale SW-Cs können in einer gemeinsamen vertrauenswürdigen Partition (OS-Application 1, Supervisor Mode) ausgeführt werden, wenn sie demselben Integritätslevel entsprechen oder gemeinsam qualifiziert sind.</li>\n<li>Nicht-vertrauenswürdige Software-Komponenten müssen in getrennte User-Mode-OS-Applications ausgelagert werden, um Schutz vor unberechtigten Speicherüberschreibungen fremder Applikationen oder der Basissoftware sicherzustellen.</li>\n<li>Datenflüsse zwischen unterschiedlichen Sicherheitsdomänen dürfen nicht direkt über ungeschützte globale Variablen abgewickelt werden, sondern erfordern RTE-vermittelte Schnittstellen und kontrollierte Kommunikationspuffer.</li>\n</ul>"}, {"id": "FIG-0d41a766e35dbdcf", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Speicherschutzdiagramm (AUTOSAR Classic Platform, Schichtenarchitektur im Kontext des Safety Concept Status Reports). Das Diagramm visualisiert das Konzept der Speicherpartitionierung (Memory Partitioning) und CPU-Betriebsmodi (CPU User Mode vs. CPU Supervisor Mode) zur Trennung von vertrauenswürdigen (trusted) und nicht-vertrauenswürdigen (non-trusted) OS-Applications, inklusive der Zuordnung von Software-Komponenten (SW-Cs) und Basissoftware-Modulen (BSWMs) sowie der Speicheraufteilung in private und geteilte Bereiche.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich vertikal in ECU-Hardware, Basic Software (BSW), AUTOSAR Runtime Environment (RTE) und die AUTOSAR-Software-Anwendungsschicht.</p>\n<ul class=\"fig-list\">\n<li>Entitäten und Partitionen:</li>\n<li>Nicht-vertrauenswürdige Partitionen (grün umrandet, CPU User Mode): „Non-trusted OS-Applications, with protection enabled“. SW-Cs sind einer oder mehreren OS-Applications zugeordnet (z. B. linke Application Software Component in einer eigenen Partition; Actuator Software Component und Sensor Software Component gemeinsam in einer weiteren Partition).</li>\n<li>Vertrauenswürdige Partition (rot hinterlegt/umrandet, CPU Supervisor Mode): Bildet „OS-Application 1, trusted, with protection disabled“. Diese umfasst sämtliche Basissoftware-Module, die RTE sowie ausgewählte vertrauenswürdige Anwendungs-SW-Cs (vierte Application Software Component).</li>\n<li>BSW-Module: Operating System (OS), Services, Communication, ECU Abstraction, Microcontroller Abstraction (MCAL) und Complex Device Drivers (CDD).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellen:</li>\n<li>AUTOSAR Interface: Zwischen Anwendungs-SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li>Standardized AUTOSAR Interface: Zwischen RTE und Services.</li>\n<li>Standardized Interface: Zwischen RTE und BSW (Services, Communication, OS-Schnittstellenblock), zwischen BSW-Modulen untereinander (Services, Communication, ECU Abstraction zum OS; ECU Abstraction zu MCAL) sowie an der vertikalen OS-Schnittstelle („Standardized Inteface“).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Speicheraufteilung (Memory-Säule rechts):</li>\n<li>Private Datenbereiche: OS-App 1 private data, OS-App 2 private data, ..., OS-App n private data.</li>\n<li>Private Codebereiche: OS-App 1 private code, OS-App 2 private code, ..., OS-App n private code.</li>\n<li>Geteilter Speicherbereich: „Optional: shared OS-App 1 data (buffer used by RTE for IPC)“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsdiagramm ohne explizite Ablauf- oder Zeitsequenzen. Das dynamische Zusammenspiel basiert auf den Privilegiierungsstufen:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs in nicht-vertrauenswürdigen Partitionen führen Code im CPU User Mode aus; Speicherzugriffe werden hardwaregestützt (MPU) auf die jeweiligen privaten Daten- und Codebereiche begrenzt.</li>\n<li>BSW-Module und vertrauenswürdige SW-Cs führen Code im CPU Supervisor Mode ohne Zugriffsbeschränkungen aus.</li>\n<li>Inter-OS-Application-Kommunikation (IPC) zwischen Partitionen erfolgt vermittelt über die RTE unter Verwendung definierter Puffer im Shared Memory („shared OS-App 1 data“). BSW-Dienste werden über standardisierte Schnittstellen und Systemaufrufe an das Betriebssystem angefordert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sicherheitstechnisches Architekturmuster zur Gewährleistung der Rückwirkungsfreiheit (Freedom from Interference gemäß ISO 26262):</p>\n<ul class=\"fig-list\">\n<li>Basissoftware und ausgewählte funktionale SW-Cs können in einer gemeinsamen vertrauenswürdigen Partition (OS-Application 1, Supervisor Mode) ausgeführt werden, wenn sie demselben Integritätslevel entsprechen oder gemeinsam qualifiziert sind.</li>\n<li>Nicht-vertrauenswürdige Software-Komponenten müssen in getrennte User-Mode-OS-Applications ausgelagert werden, um Schutz vor unberechtigten Speicherüberschreibungen fremder Applikationen oder der Basissoftware sicherzustellen.</li>\n<li>Datenflüsse zwischen unterschiedlichen Sicherheitsdomänen dürfen nicht direkt über ungeschützte globale Variablen abgewickelt werden, sondern erfordern RTE-vermittelte Schnittstellen und kontrollierte Kommunikationspuffer.</li>\n</ul>"}], "trans": [{"from": "FIG-6e695b3447703dcb", "to": "FIG-b7f603315cf2ab59", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b7f603315cf2ab59", "to": "FIG-4af1386b469f084e", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4af1386b469f084e", "to": "FIG-0d41a766e35dbdcf", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
